function matchAnalysisForm(m){const a=m.analysis||{},w=a.w5||{},fr=a.functionRatings||{};return `<div class="form-grid"><div class="field full"><h3>1. Beschrijf / lees het voetbal</h3><p class="muted small">KNVB-lijn: wat zie ik → wat levert het op → waarom gebeurt het? Daarna: mogelijke oplossingen vergelijken en één oplossing trainen.</p></div>${Object.entries(TEAM_FUNCTION_LABELS).map(([k,l])=>`<div class="field"><label>${l}</label>${analysisSelect(k,fr[k]||'')}</div>`).join('')}<div class="field full"><label>Wat zie ik?</label><textarea id="anSee">${esc(a.see||'')}</textarea></div><div class="field full"><label>Wat levert het op?</label><textarea id="anYield">${esc(a.yield||'')}</textarea></div><div class="field full"><h3>2. Diagnose</h3></div><div class="field full"><label>Waarom gebeurt het?</label><textarea id="anWhy">${esc(a.why||'')}</textarea></div><div class="field"><label>Dominante oorzaak</label><select id="anRootCause">${['','Tactisch','Technisch','Fysiek','Mentaal / besluitvorming','Gemengd'].map(x=>`<option ${a.rootCause===x?'selected':''}>${x||'Niet gekozen'}</option>`).join('')}</select></div><div class="field full"><label>Voetbaluitdaging</label><textarea id="anChallenge">${esc(a.challenge||'')}</textarea></div><div class="field full"><h3>5 W's</h3></div><div class="field full"><label>Wat gaat mis / moet beter?</label><textarea id="wWhat">${esc(w.what||'')}</textarea></div><div class="field"><label>Waar?</label><input id="wWhere" class="input" value="${esc(w.where||'')}"></div><div class="field"><label>Wie / welke posities?</label><input id="wWho" class="input" value="${esc(w.who||'')}"></div><div class="field"><label>Wanneer?</label><input id="wWhen" class="input" value="${esc(w.when||'')}"></div><div class="field"><label>Omstandigheden / tegenpartij</label><input id="wCirc" class="input" value="${esc(w.circumstances||'')}"></div><div class="field full"><h3>3. Exploreer oplossingen</h3><p class="muted tiny">Noteer meerdere opties voordat je kiest. Denk aan trade-offs en wat je spelers werkelijk kunnen uitvoeren.</p></div>${[1,2,3].map(n=>`<div class="field full"><label>Optie ${n}</label><textarea id="anSolution${n}">${esc((a.solutions||[])[n-1]||'')}</textarea></div>`).join('')}<div class="field full"><label>Gekozen oplossing</label><textarea id="anSelectedSolution">${esc(a.selectedSolution||'')}</textarea></div><div class="field full"><h3>4. Plan</h3></div><div class="field full"><label>Hoe train ik deze oplossing?</label><textarea id="anTrainingPlan" placeholder="Van eenvoudig/herkenbaar naar wedstrijdrealistisch; eindig met spelvorm waarin de oplossing nodig is.">${esc(a.trainingPlan||'')}</textarea></div><div class="field full"><label>Rustbespreking / bijsturing</label><textarea id="anHalf">${esc(a.halftime||'')}</textarea></div><div class="field full"><label>Reflectie eigen handelen</label><textarea id="anReflection">${esc(a.reflection||'')}</textarea></div><div class="field full"><label>Feedback begeleidingsteam</label><textarea id="anStaff">${esc(a.staffFeedback||'')}</textarea></div></div>`}
function editMatchAnalysis(id){const m=matchById(id);if(!m)return;modal('Wedstrijdanalyse · diagnose → oplossing → training',matchAnalysisForm(m),()=>{m.analysis={functionRatings:Object.fromEntries(Object.keys(TEAM_FUNCTION_LABELS).map(k=>[k,$(`#analysis-${k}`).value])),see:$('#anSee').value.trim(),yield:$('#anYield').value.trim(),why:$('#anWhy').value.trim(),rootCause:$('#anRootCause').value,challenge:$('#anChallenge').value.trim(),w5:{what:$('#wWhat').value.trim(),where:$('#wWhere').value.trim(),who:$('#wWho').value.trim(),when:$('#wWhen').value.trim(),circumstances:$('#wCirc').value.trim()},solutions:[1,2,3].map(n=>$(`#anSolution${n}`).value.trim()).filter(Boolean),selectedSolution:$('#anSelectedSolution').value.trim(),trainingPlan:$('#anTrainingPlan').value.trim(),halftime:$('#anHalf').value.trim(),reflection:$('#anReflection').value.trim(),staffFeedback:$('#anStaff').value.trim(),updatedAt:new Date().toISOString()};return true},{saveText:'Analyse opslaan'})}
function diagnosticScoreLabel(v){v=number(v);if(!v)return 'Niet beoordeeld';if(v<40)return 'Gerichte aandacht';if(v<60)return 'Kwetsbaar';if(v<80)return 'Goed';return 'Sterk'}
function diagnosticSummary(d){if(!d)return null;const flat=Object.values(TEAM_DIAGNOSTIC_GROUPS).flat(),scores=flat.map(([k,l])=>({key:k,label:l,value:number(d.scores?.[k])})).filter(x=>x.value>0),groups=Object.fromEntries(Object.entries(TEAM_DIAGNOSTIC_GROUPS).map(([g,items])=>{const vals=items.map(([k])=>number(d.scores?.[k])).filter(Boolean);return [g,vals.length?Math.round(vals.reduce((a,b)=>a+b,0)/vals.length):0]})),lowest=scores.sort((a,b)=>a.value-b.value)[0]||null;return {groups,lowest,overall:scores.length?Math.round(scores.reduce((a,b)=>a+b.value,0)/scores.length):0}}
function editTeamDiagnostic(id){const existing=id?(state.teamDiagnostics||[]).find(x=>x.id===id):null,last=existing||(state.teamDiagnostics||[]).filter(x=>x.teamId===ui.teamId).sort((a,b)=>(b.date||'').localeCompare(a.date||''))[0]||{},scores=last.scores||{};modal(existing?'Teamdiagnose bewerken':'Nieuwe teamdiagnose',`<p class="muted small">Beoordeel 11 gebieden op 1–100. Gebruik wedstrijd- en trainingsobservaties, niet alleen gevoel.</p><div class="diagnostic-form">${Object.entries(TEAM_DIAGNOSTIC_GROUPS).map(([group,items])=>`<section><h3>${group}</h3>${items.map(([k,l])=>`<div class="diagnostic-input"><label>${l}</label><input id="diag-${k}" class="input" type="number" inputmode="numeric" min="1" max="100" value="${number(scores[k])||''}" placeholder="1–100"></div>`).join('')}</section>`).join('')}</div><div class="field"><label>Korte observatie / context</label><textarea id="diagNotes">${esc(existing?.notes||'')}</textarea></div>`,()=>{const obj=existing||{id:uid('diag'),teamId:ui.teamId,date:TODAY(),scores:{}};obj.date=TODAY();obj.notes=$('#diagNotes').value.trim();obj.scores={};Object.values(TEAM_DIAGNOSTIC_GROUPS).flat().forEach(([k])=>obj.scores[k]=Math.round(clamp(number($(`#diag-${k}`).value),0,100)));obj.updatedAt=new Date().toISOString();if(!existing)state.teamDiagnostics.push(obj);return true},{saveText:'Diagnose opslaan'})}
function trainingFromDiagnostic(){const d=(state.teamDiagnostics||[]).filter(x=>x.teamId===ui.teamId).sort((a,b)=>(b.date||'').localeCompare(a.date||''))[0],sum=diagnosticSummary(d);if(!sum?.lowest)return toast('Vul eerst een teamdiagnose in');const focus=sum.lowest.label,nt=nextTraining(ui.teamId),text=`Teamdiagnose ${fmtDate(d.date)}: ${focus} ${sum.lowest.value}/100.`;if(nt&&confirm(`Koppel “${focus}” als focus aan de eerstvolgende training op ${fmtDate(nt.date)}?`)){nt.focus=focus;nt.startingSituation=[nt.startingSituation,text].filter(Boolean).join('\n');nt.trainingObjective=nt.trainingObjective||`Verbeteren van ${focus.toLowerCase()} in herkenbare wedstrijdsituaties.`;ui.trainingId=nt.id;save();setPage('trainings');return}const dt=new Date();dt.setDate(dt.getDate()+2);const t={id:uid('tr'),date:dt.toLocaleDateString('sv-SE'),title:'Training',startTime:state.team.trainingTime||'20:00',teamId:ui.teamId,templateKey:'match',templateName:'Wedstrijdgerichte training',attendance:{},squadPlayerIds:null,notes:'',coachNotes:'',focus,intensity:'Middel',trainingObjective:`Verbeteren van ${focus.toLowerCase()} in herkenbare wedstrijdsituaties.`,startingSituation:text,footballChallenge:focus,planItems:[],exerciseIds:[],quickReflection:{}};state.trainings.push(t);ui.trainingId=t.id;save();setPage('trainings')}
function idpGoalCard(p,g){const status=g.status||'Actief',cls=status==='Behaald'?'green':status==='Gepauzeerd'?'orange':'';return `<article class="idp-goal"><div class="idp-goal-head"><div><span class="badge ${cls}">${esc(status)}</span><strong>${esc(g.title||'Ontwikkeldoel')}</strong><small>${esc(g.area||'Ontwikkeling')}${g.reviewDate?` · evaluatie ${fmtDate(g.reviewDate)}`:''}</small></div><div class="row-actions"><button class="btn ghost small-btn" data-idp-training="${p.id}" data-goal-id="${g.id}">Training</button><button class="btn ghost small-btn" data-edit-idp="${p.id}" data-goal-id="${g.id}">Bewerk</button></div></div><div class="idp-progress"><span style="width:${clamp(number(g.progress),0,100)}%"></span></div><div class="idp-grid"><div><span>Meetpunt</span><p>${nl2br(g.measure||'Nog niet ingevuld')}</p></div><div><span>Acties</span><p>${nl2br(g.actions||'Nog niet ingevuld')}</p></div></div></article>`}
function editIdpGoal(playerId,goalId=''){const p=playerById(playerId);if(!p)return;p.idp??={goals:[]};const g=goalId?p.idp.goals.find(x=>x.id===goalId):null;const active=p.idp.goals.filter(x=>(x.status||'Actief')==='Actief').length;if(!g&&active>=3&&!confirm('Deze speler heeft al 3 actieve doelen. Toch nog een doel toevoegen?'))return;modal(g?'Ontwikkeldoel bewerken':'Nieuw individueel ontwikkeldoel',`<div class="form-grid"><div class="field full"><label>Doel</label><input id="idpTitle" class="input" placeholder="Bijv. vóór ontvangen scannen en open draaien" value="${esc(g?.title||'')}"></div><div class="field"><label>Gebied</label><select id="idpArea">${IDP_AREAS.map(x=>`<option ${g?.area===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Status</label><select id="idpStatus">${['Actief','Behaald','Gepauzeerd'].map(x=>`<option ${g?.status===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="field"><label>Voortgang 0–100</label><input id="idpProgress" class="input" type="number" min="0" max="100" value="${number(g?.progress)||0}"></div><div class="field"><label>Volgende evaluatie</label><input id="idpReview" class="input" type="date" value="${esc(g?.reviewDate||'')}"></div><div class="field full"><label>SMART / meetpunt</label><textarea id="idpMeasure" placeholder="Hoe weten speler en coach dat dit beter gaat?">${esc(g?.measure||'')}</textarea></div><div class="field full"><label>Actieplan</label><textarea id="idpActions" placeholder="Wat doet de speler? Wat doe jij als coach?">${esc(g?.actions||'')}</textarea></div></div>`,()=>{const title=$('#idpTitle').value.trim();if(!title){toast('Vul een doel in');return false}const obj=g||{id:uid('goal'),createdAt:new Date().toISOString()};Object.assign(obj,{title,area:$('#idpArea').value,status:$('#idpStatus').value,progress:Math.round(clamp(number($('#idpProgress').value),0,100)),reviewDate:$('#idpReview').value,measure:$('#idpMeasure').value.trim(),actions:$('#idpActions').value.trim(),updatedAt:new Date().toISOString()});if(!g)p.idp.goals.push(obj);p.idp.updatedAt=new Date().toISOString();return true},{saveText:'Doel opslaan'})}
function trainingFromIdp(playerId,goalId){const p=playerById(playerId),g=p?.idp?.goals?.find(x=>x.id===goalId);if(!p||!g)return;const dt=new Date();dt.setDate(dt.getDate()+2);const t={id:uid('tr'),date:dt.toLocaleDateString('sv-SE'),title:'Training',startTime:state.team.trainingTime||'20:00',teamId:p.primaryTeamId||ui.teamId,templateKey:'development',templateName:'Ontwikkeltraining',attendance:{},squadPlayerIds:null,notes:`Individuele focus: ${p.name}`,coachNotes:`IDP ${p.name}: ${g.title}\nMeetpunt: ${g.measure||'–'}\nActies: ${g.actions||'–'}`,focus:`${p.name} · ${g.title}`,intensity:'Middel',trainingObjective:g.title,startingSituation:`Individueel ontwikkelplan · ${g.area}`,footballChallenge:g.title,planItems:[],exerciseIds:[],quickReflection:{}};state.trainings.push(t);ui.teamId=t.teamId;ui.trainingId=t.id;save();setPage('trainings');toast('Ontwikkeltraining gemaakt')}
function activityReflectionForm(ev,type){const r=ev.quickReflection||{},focus=r.focus||(type==='Training'?(ev.trainingObjective||ev.focus):(ev.plan?.teamGoal||ev.analysis?.challenge||''));return `<div class="form-grid"><div class="field full"><label>1. Wat was de focus?</label><textarea id="qrFocus">${esc(focus||'')}</textarea></div><div class="field full"><label>2. Wat ging goed?</label><textarea id="qrGood">${esc(r.good||'')}</textarea></div><div class="field full"><label>3. Wat werkte niet / minder?</label><textarea id="qrBad">${esc(r.bad||'')}</textarea></div><div class="field full"><label>4. Spelerobservaties</label><textarea id="qrPlayers">${esc(r.players||'')}</textarea></div><div class="field full"><label>5. Wat is de volgende stap?</label><textarea id="qrNext">${esc(r.next||'')}</textarea></div><div class="field"><label>Optioneel: koppel observatie aan speler</label><select id="qrPlayerId"><option value="">Geen speler</option>${playersForTeam(ev.teamId).map(p=>`<option value="${p.id}" ${r.playerId===p.id?'selected':''}>${esc(p.name)}</option>`).join('')}</select></div><div class="field"><label>Korte individuele observatie</label><input id="qrPlayerNote" class="input" value="${esc(r.playerNote||'')}"></div></div>`}
function editQuickReflection(kind,id){const ev=kind==='training'?trainingById(id):matchById(id);if(!ev)return;const type=kind==='training'?'Training':'Wedstrijd';modal(`2-minutenreflectie · ${type}`,activityReflectionForm(ev,type),()=>{const old=ev.quickReflection||{},playerId=$('#qrPlayerId').value,playerNote=$('#qrPlayerNote').value.trim();ev.quickReflection={focus:$('#qrFocus').value.trim(),good:$('#qrGood').value.trim(),bad:$('#qrBad').value.trim(),players:$('#qrPlayers').value.trim(),next:$('#qrNext').value.trim(),playerId,playerNote,noteId:old.noteId||'',updatedAt:new Date().toISOString()};if(kind==='training'&&ev.quickReflection.next&&!ev.trainingEvaluation?.next){ev.trainingEvaluation??={};ev.trainingEvaluation.next=ev.quickReflection.next}if(kind==='match'&&ev.quickReflection.next&&!ev.evaluation?.nextTraining){ev.evaluation??={};ev.evaluation.nextTraining=ev.quickReflection.next}if(playerId&&playerNote){let note=old.noteId?state.coachNotes.find(n=>n.id===old.noteId):null;if(!note){note={id:uid('note'),date:TODAY(),teamId:ev.teamId,playerId,category:`${type}observatie`,text:playerNote};state.coachNotes.push(note);ev.quickReflection.noteId=note.id}else{note.playerId=playerId;note.text=playerNote;note.date=TODAY()}}return true},{saveText:'Reflectie opslaan'})}
function trainingFromAnalysis(id){const m=matchById(id);if(!m)return;const a=m.analysis||{},focus=a.selectedSolution||a.challenge||a.w5?.what;if(!focus)return toast('Vul eerst een voetbaluitdaging of gekozen oplossing in');const nt=state.trainings.filter(t=>t.teamId===m.teamId&&t.date>m.date&&!isCancelled(t)).sort((x,y)=>x.date.localeCompare(y.date))[0],context=`Wedstrijdanalyse ${fmtDate(m.date)} vs ${m.opponent||'tegenstander'}: ${a.challenge||a.w5?.what||''}${a.rootCause?` · oorzaak: ${a.rootCause}`:''}${a.selectedSolution?` · oplossing: ${a.selectedSolution}`:''}`;if(nt&&confirm(`Koppel deze analyse aan de eerstvolgende training op ${fmtDate(nt.date)}?`)){nt.focus=focus;nt.startingSituation=[nt.startingSituation,context].filter(Boolean).join('\n');nt.footballChallenge=a.challenge||a.w5?.what||focus;nt.trainingObjective=a.trainingPlan||`Verbeteren van ${focus.toLowerCase()} in een herkenbare wedstrijdcontext.`;ui.trainingId=nt.id;save();setPage('trainings');return}const d=new Date(m.date+'T12:00:00');d.setDate(d.getDate()+3);const t={id:uid('tr'),date:d.toLocaleDateString('sv-SE'),title:'Training',startTime:state.team.trainingTime||'20:00',teamId:m.teamId,templateKey:'match',templateName:'Wedstrijdgerichte training',attendance:{},squadPlayerIds:null,notes:'',coachNotes:'',focus,intensity:'Middel',trainingObjective:a.trainingPlan||`Verbeteren van ${focus.toLowerCase()} in een herkenbare wedstrijdcontext.`,startingSituation:context,footballChallenge:a.challenge||a.w5?.what||focus,methodicalProgression:'Van herkenning van het probleem naar een spelvorm met volledige weerstand.',planItems:[],exerciseIds:[],quickReflection:{}};state.trainings.push(t);ui.trainingId=t.id;save();setPage('trainings')}

function editCoachReflection(){const last=(state.coachReflections||[]).find(x=>x.week===currentWeekKey()&&x.teamId===ui.teamId)||{};modal('Weekreflectie coach',`<p class="muted small">Reflecteer op vier kwaliteiten: structureren, stimuleren, individuele aandacht en regie overdragen.</p><div class="form-grid">${Object.entries(COACH_QUALITY_LABELS).map(([k,l])=>`<div class="field"><label>${l} (1–5)</label><input id="cq-${k}" class="input" type="number" min="1" max="5" value="${number(last[k])||3}"></div>`).join('')}<div class="field full"><label>Wat ging goed?</label><textarea id="cqGood">${esc(last.good||'')}</textarea></div><div class="field full"><label>Volgende coachactie</label><textarea id="cqNext">${esc(last.next||'')}</textarea></div></div>`,()=>{const obj={id:last.id||uid('cr'),week:currentWeekKey(),date:TODAY(),teamId:ui.teamId,good:$('#cqGood').value.trim(),next:$('#cqNext').value.trim()};Object.keys(COACH_QUALITY_LABELS).forEach(k=>obj[k]=Math.max(1,Math.min(5,number($(`#cq-${k}`).value)||3)));state.coachReflections??=[];const i=state.coachReflections.findIndex(x=>x.id===obj.id);if(i>=0)state.coachReflections[i]=obj;else state.coachReflections.push(obj);return true})}
function staffMemberForm(x={}){return `<div class="form-grid"><div class="field"><label>Naam</label><input id="staffName" class="input" value="${esc(x.name||'')}"></div><div class="field"><label>Rol</label><input id="staffRole" class="input" placeholder="Assistent / leider / keeperstrainer" value="${esc(x.role||'')}"></div><div class="field full"><label>Taken & verantwoordelijkheden</label><textarea id="staffTasks">${esc(x.tasks||'')}</textarea></div><div class="field full"><label>Wat verwacht ik van deze rol?</label><textarea id="staffExpect">${esc(x.expectations||'')}</textarea></div><div class="field full"><label>Verbeteractie / afspraak</label><textarea id="staffAction">${esc(x.action||'')}</textarea></div></div>`}
function editStaffMember(id){const x=id?(state.staff||[]).find(y=>y.id===id):null;modal(x?'Staflid bewerken':'Staflid toevoegen',staffMemberForm(x||{}),()=>{const name=$('#staffName').value.trim();if(!name){toast('Vul een naam in');return false}const obj=x||{id:uid('staff')};Object.assign(obj,{name,role:$('#staffRole').value.trim(),tasks:$('#staffTasks').value.trim(),expectations:$('#staffExpect').value.trim(),action:$('#staffAction').value.trim()});if(!x)state.staff.push(obj);return true})}
function renderCoachToolkit(){const reflection=(state.coachReflections||[]).filter(x=>x.teamId===ui.teamId).sort((a,b)=>(b.date||'').localeCompare(a.date||''))[0],diagnostics=(state.teamDiagnostics||[]).filter(x=>x.teamId===ui.teamId).sort((a,b)=>(b.date||'').localeCompare(a.date||'')),diag=diagnostics[0],ds=diagnosticSummary(diag);return `<div class="toolbar"><div class="left"><button class="btn primary" data-team-diagnostic>＋ Teamdiagnose</button><button class="btn ghost" data-coach-reflection>＋ Weekreflectie</button><button class="btn ghost" data-add-staff>＋ Staflid</button></div></div><section class="card diagnostic-card"><div class="card-head"><div><p class="eyebrow">5-MINUTEN TEAMDIAGNOSE</p><h2>Waar zit nu de grootste voetbaluitdaging?</h2><p class="muted small">11 gebieden · 1–100 · technisch, tactisch, fysiek en mentaal</p></div>${diag?`<span class="badge green">${fmtDate(diag.date)}</span>`:''}</div>${ds?`<div class="diagnostic-overview"><div class="diagnostic-big"><span>Teambeeld</span><strong>${ds.overall}</strong><small>/100</small></div>${Object.entries(ds.groups).map(([g,v])=>`<div class="diagnostic-group"><span>${g}</span><strong>${v||'–'}</strong><div class="mini-track"><i style="width:${v||0}%"></i></div></div>`).join('')}</div><div class="diagnostic-low"><div><span class="eyebrow">LAAGSTE SCORE</span><strong>${esc(ds.lowest?.label||'–')} · ${ds.lowest?.value||'–'}/100</strong><p class="muted small">${ds.lowest?diagnosticScoreLabel(ds.lowest.value):''}</p></div><button class="btn primary" data-training-from-diagnostic>Maak training hiervan</button></div>${diag.notes?`<div class="callout"><strong>Observatie</strong><p>${nl2br(diag.notes)}</p></div>`:''}`:'<div class="empty">Nog geen teamdiagnose. Vul in 5 minuten een eerste teambeeld in.</div>'}</section><div class="grid two" style="margin-top:16px"><section class="card"><div class="card-head"><div><p class="eyebrow">COACHKOMPAS</p><h2>Lezen → analyseren → beïnvloeden</h2></div></div><div class="coach-flow"><div><b>1</b><strong>Wat zie ik?</strong><span>Teamfuncties, teamtaken en voetbalhandelingen</span></div><div><b>2</b><strong>Wat levert het op?</strong><span>Betekenis in relatie tot de spelbedoeling</span></div><div><b>3</b><strong>Waarom?</strong><span>Verband eigen team ↔ tegenpartij</span></div><div><b>4</b><strong>Voetbaluitdaging</strong><span>Concreet met de 5 W's</span></div><div><b>5</b><strong>Wat doe / zeg ik?</strong><span>Coachen met PMRS en vragen</span></div></div></section><section class="card"><div class="card-head"><div><p class="eyebrow">VIER KWALITEITEN</p><h2>Coachreflectie</h2></div><button class="btn ghost small-btn" data-coach-reflection>Bewerk</button></div>${reflection?`<div class="quality-grid">${Object.entries(COACH_QUALITY_LABELS).map(([k,l])=>`<div><span>${l}</span><strong>${reflection[k]}/5</strong></div>`).join('')}</div><div class="callout" style="margin-top:12px"><strong>Volgende actie</strong><p>${nl2br(reflection.next||'Nog niet ingevuld')}</p></div>`:'<div class="empty">Nog geen weekreflectie.</div>'}</section></div><div class="grid two" style="margin-top:16px"><section class="card"><div class="card-head"><div><p class="eyebrow">TRAINING</p><h2>Vier eisen</h2></div></div>${Object.values(TRAINING_REQUIREMENTS).map(x=>`<div class="list-row"><span>${esc(x)}</span><strong>✓</strong></div>`).join('')}<p class="muted small">Gebruik Trainingen → Evalueren om deze eisen per training vast te leggen.</p></section><section class="card"><div class="card-head"><div><p class="eyebrow">VEILIG SPORTKLIMAAT</p><h2>Gedragsanker</h2></div></div><p class="muted small">Veilige omgeving, voorbeeldgedrag, respect voor privacy en verschillen, grenzen bewaken, vertrouwelijk omgaan met persoonlijke informatie en alert handelen bij signalen.</p><div class="callout"><strong>Praktische regel</strong><p>Spelerinformatie in deze app is coachinformatie: deel alleen wat voor begeleiding noodzakelijk is.</p></div></section></div><section class="card" style="margin-top:16px"><div class="card-head"><div><p class="eyebrow">BEGELEIDINGSTEAM</p><h2>Rollen, taken & verwachtingen</h2></div><button class="btn primary small-btn" data-add-staff>＋ Staflid</button></div>${state.staff.length?state.staff.map(x=>`<div class="staff-row"><div><strong>${esc(x.name)}</strong><span>${esc(x.role||'Rol niet ingevuld')}</span><small>${esc(x.tasks||'Nog geen taken vastgelegd')}</small></div><button class="btn ghost small-btn" data-edit-staff="${x.id}">Bewerk</button></div>`).join(''):'<div class="empty">Leg per staflid rol, taken, verantwoordelijkheden en verbeteracties vast.</div>'}</section>`}
function trainingPdfValue(label,value){return `<div class="info-cell"><span>${esc(label)}</span><strong>${value?esc(value):'–'}</strong></div>`}
function trainingPdfBlock(title,value,extraClass=''){return `<section class="detail-block ${extraClass}"><h3>${esc(title)}</h3><div>${value?nl2br(value):'<span class="muted-print">–</span>'}</div></section>`}
function buildTrainingSheetHtml(t){
  const team=state.teams.find(x=>x.id===t.teamId)||activeTeam(),meta=trainingTemplateMeta(t),squad=eventSquad(t),duration=(t.planItems||[]).reduce((a,x)=>a+number(x.duration),0),season=state.team.season||'',club=state.club?.name||'DSV Full Speed';
  const planRows=(t.planItems||[]).map((pi,i)=>{const ex=exerciseById(pi.exerciseId);return `<tr><td>${i+1}</td><td><strong>${esc(ex?.name||'Oefening')}</strong><small>${esc(ex?.category||'')}</small></td><td>${esc(ex?.players||'–')}</td><td>${number(pi.duration)} min</td></tr>`}).join('');
  const exercisePages=(t.planItems||[]).map((pi,i)=>{const ex=exerciseById(pi.exerciseId)||{},points=(pi.coachPoints?.length?pi.coachPoints:ex.coachPoints||[]),note=pi.notes||'',method=[ex.easier?`Makkelijker: ${ex.easier}`:'',ex.harder?`Moeilijker: ${ex.harder}`:''].filter(Boolean).join('\n'),chips=[`${number(pi.duration)} min`,ex.category||'',ex.intensity||'',ex.players?`${ex.players} spelers`:'',ex.size||''].filter(Boolean).map(x=>`<span>${esc(x)}</span>`).join('');return `<article class="sheet exercise-sheet"><header class="exercise-head"><div class="mini-club"><img src="${FULL_SPEED_LOGO_DATA}" alt="Full Speed"><div><small>${esc(team?.name||'Team')} · ${fmtDate(t.date)}</small><strong>Oefening ${i+1} van ${t.planItems.length}</strong></div></div><div class="exercise-number">${i+1}</div></header><div class="exercise-title"><p>${esc(ex.category||'OEFENING')}</p><h1>${esc(ex.name||'Oefening')}</h1><div class="exercise-chips">${chips}</div></div><div class="exercise-grid">${trainingPdfBlock('Doel',ex.goal||ex.description||'')}${trainingPdfBlock('Organisatie / uitvoering',ex.organization||ex.description||'','wide')}${trainingPdfBlock('Coachpunten',points.length?points.map(x=>`• ${x}`).join('\n'):'','coach-box wide')}${note?trainingPdfBlock('Specifiek voor deze training',note,'wide highlight'):''}${trainingPdfBlock('Materiaal',ex.materials||'')}${trainingPdfBlock('Voetbalweerstanden',ex.resistances||'')}${trainingPdfBlock('Methodiek',method||ex.variations||'','wide')}${ex.variations&&method?trainingPdfBlock('Variaties / progressies',ex.variations,'wide'):''}</div><footer class="pdf-footer"><span>${esc(club)} · ${esc(team?.name||'')}</span><span>Training ${fmtDate(t.date)} · oefening ${i+1}/${t.planItems.length}</span></footer></article>`}).join('');
  return `<!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Training ${esc(team?.name||'')} ${esc(t.date)}</title><style>
@page{size:A4;margin:0}*{box-sizing:border-box;-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important}html,body{margin:0;padding:0;background:#e8efeb;color:#16392f;font-family:Inter,Arial,sans-serif}.print-actions{position:sticky;top:0;z-index:20;background:#102f26;color:#fff;padding:10px;display:flex;justify-content:center;gap:10px;flex-wrap:wrap}.print-actions button{border:0;border-radius:10px;padding:10px 16px;font-weight:800;cursor:pointer}.print-actions .primary{background:#0b6b44;color:#fff}.share-hint{max-width:210mm;margin:8px auto 0;padding:8px 12px;border-radius:10px;background:#fff;color:#546a60;font-size:12px;text-align:center}.sheet{position:relative;width:210mm;min-height:297mm;margin:12px auto;background:#fff;padding:12mm 13mm 10mm;box-shadow:0 14px 38px #17392f22;break-after:page;page-break-after:always;overflow:hidden}.sheet:last-child{break-after:auto;page-break-after:auto}.cover-hero{margin:-12mm -13mm 0;padding:11mm 13mm 10mm;background:linear-gradient(135deg,#073c2d,#0b6b44);color:#fff}.club-row{display:flex;align-items:center;gap:5mm}.crest{width:16mm;height:16mm;object-fit:contain;background:#fff;border-radius:50%;padding:1.4mm}.club-row small{display:block;text-transform:uppercase;letter-spacing:1.5px;opacity:.8;font-size:7pt}.club-row strong{font-size:14pt}.cover-title{margin-top:8mm;display:grid;grid-template-columns:1fr auto;gap:8mm;align-items:end}.cover-title h1{font-size:29pt;line-height:1;margin:0 0 2mm}.cover-title p{margin:0;opacity:.84;font-size:10pt}.template-pill{border:1px solid #ffffff55;background:#ffffff12;border-radius:4mm;padding:4mm 5mm;text-align:right;min-width:47mm}.template-pill span{display:block;font-size:6.5pt;text-transform:uppercase;letter-spacing:1px}.template-pill strong{display:block;font-size:12pt;margin-top:1mm}.overview-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:2.5mm;margin:5mm 0}.info-cell{border:1px solid #dbe7e0;border-radius:3mm;padding:3mm;background:#fbfcfb;min-height:17mm}.info-cell span{display:block;color:#74867d;text-transform:uppercase;letter-spacing:.6px;font-size:6.5pt}.info-cell strong{display:block;margin-top:1.2mm;font-size:9pt;line-height:1.25}.section-title{display:flex;justify-content:space-between;align-items:end;border-bottom:1px solid #ccdcd3;padding-bottom:1.5mm;margin:5mm 0 3mm}.section-title h2{margin:0;color:#07583a;font-size:14pt}.section-title span{font-size:7pt;color:#7b8b83;text-transform:uppercase;letter-spacing:.8px}.goal-card{background:#eef6f1;border-left:4px solid #0b6b44;border-radius:0 3mm 3mm 0;padding:3.5mm 4mm;font-size:9pt;line-height:1.45}.summary-grid{display:grid;grid-template-columns:1fr 1fr;gap:3mm}.summary-card{border:1px solid #dce6e0;border-radius:3mm;padding:3.5mm;background:#fbfcfb;min-height:25mm}.summary-card h3{margin:0 0 1.5mm;color:#07583a;font-size:9pt}.summary-card div{font-size:8pt;line-height:1.4;color:#3c554a}.plan-table{width:100%;border-collapse:collapse;font-size:8pt}.plan-table th{background:#0b6b44;color:#fff;text-align:left;padding:2.5mm}.plan-table td{border-bottom:1px solid #e0e8e3;padding:2.5mm;vertical-align:top}.plan-table td:first-child{width:9mm;font-weight:900;color:#0b6b44}.plan-table td:last-child{width:22mm;font-weight:800}.plan-table small{display:block;color:#78887f;margin-top:.8mm}.coach-note{margin-top:4mm;border:1px solid #d9e5de;border-radius:3mm;padding:3.5mm;font-size:8pt;line-height:1.4}.pdf-footer{position:absolute;left:13mm;right:13mm;bottom:7mm;display:flex;justify-content:space-between;border-top:1px solid #d9e3dd;padding-top:2mm;color:#829087;font-size:6.5pt;text-transform:uppercase;letter-spacing:.6px}.exercise-sheet{break-before:page;page-break-before:always;padding-top:9mm}.exercise-head{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid #d4e1d9;padding-bottom:3mm}.mini-club{display:flex;align-items:center;gap:3mm}.mini-club img{width:11mm;height:11mm;object-fit:contain}.mini-club small{display:block;font-size:6.5pt;color:#7d8d85;text-transform:uppercase;letter-spacing:.7px}.mini-club strong{display:block;font-size:9pt;color:#07583a}.exercise-number{width:12mm;height:12mm;border-radius:50%;display:grid;place-items:center;background:#0b6b44;color:#fff;font-size:15pt;font-weight:900}.exercise-title{padding:7mm 0 4mm}.exercise-title p{margin:0 0 1mm;color:#0b6b44;font-size:7pt;font-weight:900;letter-spacing:1.2px;text-transform:uppercase}.exercise-title h1{margin:0;font-size:25pt;line-height:1.08}.exercise-chips{display:flex;flex-wrap:wrap;gap:2mm;margin-top:3mm}.exercise-chips span{background:#eef6f1;border:1px solid #d4e5da;border-radius:99px;padding:1.5mm 2.8mm;font-size:7pt;font-weight:700}.exercise-grid{display:grid;grid-template-columns:1fr 1fr;gap:3mm}.detail-block{border:1px solid #dce6e0;border-radius:3mm;padding:4mm;background:#fbfcfb;min-height:25mm;break-inside:avoid}.detail-block.wide{grid-column:1/-1}.detail-block h3{margin:0 0 2mm;color:#07583a;font-size:10pt}.detail-block div{font-size:8.5pt;line-height:1.48;color:#344f44}.detail-block.coach-box{background:#eef6f1;border-color:#c9dfd1}.detail-block.coach-box div{font-size:9.2pt;line-height:1.6}.detail-block.highlight{border-left:4px solid #d99c32;background:#fff9ee}.muted-print{color:#89968f}.exercise-sheet .pdf-footer{left:13mm;right:13mm}.avoid{break-inside:avoid}
@media(max-width:800px){.sheet{width:100%;margin:0;box-shadow:none;padding-left:16px;padding-right:16px}.cover-hero{margin-left:-16px;margin-right:-16px;padding-left:16px;padding-right:16px}.cover-title{grid-template-columns:1fr}.template-pill{text-align:left}.overview-grid{grid-template-columns:1fr 1fr}.summary-grid,.exercise-grid{grid-template-columns:1fr}.detail-block.wide{grid-column:auto}.pdf-footer{position:static;margin-top:7mm}.exercise-sheet{min-height:auto}}
@media print{html,body{background:#fff}.print-actions,.share-hint{display:none!important}.sheet{width:210mm!important;height:297mm!important;min-height:297mm!important;margin:0!important;box-shadow:none!important;padding:12mm 13mm 10mm!important;overflow:hidden!important}.cover-hero{margin:-12mm -13mm 0!important}.overview-grid{grid-template-columns:repeat(4,1fr)!important}.summary-grid,.exercise-grid{grid-template-columns:1fr 1fr!important}.detail-block.wide{grid-column:1/-1!important}.pdf-footer{position:absolute!important}.exercise-sheet{break-before:page!important;page-break-before:always!important}}
</style></head><body><div class="print-actions"><button onclick="if(history.length>1){history.back()}else{window.close()}">← Terug</button><button class="primary" onclick="window.print()">Print / bewaar & deel als PDF</button></div><div class="share-hint">Op iPhone/iPad: kies Print, open de PDF-preview en gebruik daarna Delen om hem naar je assistent te sturen.</div><article class="sheet cover-sheet"><header class="cover-hero"><div class="club-row"><img class="crest" src="${FULL_SPEED_LOGO_DATA}" alt="Full Speed"><div><small>${esc(season?`Seizoen ${season}`:'Trainingsvoorbereiding')}</small><strong>${esc(club)} · ${esc(team?.name||'')}</strong></div></div><div class="cover-title"><div><h1>${esc(t.focus||'Training')}</h1><p>${fmtLong(t.date)} · ${esc(t.startTime||state.team.trainingTime||'')} · ${squad.length} spelers</p></div><div class="template-pill"><span>Trainingstype</span><strong>${esc(t.templateName||meta.name)}</strong></div></div></header><section class="overview-grid">${trainingPdfValue('Team',team?.name||'')}${trainingPdfValue('Duur',`${duration} min`)}${trainingPdfValue('Intensiteit',t.intensity||'')}${trainingPdfValue('Oefeningen',String((t.planItems||[]).length))}${trainingPdfValue('Teamfunctie',t.teamFunction||'')}${trainingPdfValue('Teamtaak',t.teamTask||'')}${trainingPdfValue('Serie',t.seriesName?`${t.seriesName}${t.seriesStep?` · ${t.seriesStep}/4`:''}`:'')}${trainingPdfValue('Werk-rust',t.workRest||'')}</section><div class="section-title"><h2>Globale trainingsopzet</h2><span>Pagina 1</span></div><div class="goal-card"><strong>Trainingsdoelstelling</strong><br>${t.trainingObjective?nl2br(t.trainingObjective):'<span class="muted-print">Nog niet ingevuld</span>'}</div><div class="summary-grid" style="margin-top:3mm"><div class="summary-card"><h3>Beginsituatie / aanleiding</h3><div>${t.startingSituation?nl2br(t.startingSituation):'–'}</div></div><div class="summary-card"><h3>Voetbaluitdaging / 5 W’s</h3><div>${t.footballChallenge?nl2br(t.footballChallenge):'–'}</div></div><div class="summary-card"><h3>Methodische opbouw</h3><div>${t.methodicalProgression?nl2br(t.methodicalProgression):'–'}</div></div><div class="summary-card"><h3>Aandachtspunt</h3><div>${t.templateNotes?nl2br(t.templateNotes):'–'}</div></div></div><div class="section-title"><h2>Programma</h2><span>${duration} minuten</span></div><table class="plan-table"><thead><tr><th>#</th><th>Oefening</th><th>Spelers</th><th>Duur</th></tr></thead><tbody>${planRows||'<tr><td colspan="4">Nog geen oefeningen in het trainingsplan.</td></tr>'}</tbody></table>${t.coachNotes?`<div class="coach-note"><strong>Coachnotities</strong><br>${nl2br(t.coachNotes)}</div>`:''}<footer class="pdf-footer"><span>${esc(club)} · ${esc(team?.name||'')}</span><span>${fmtDate(t.date)} · trainingsvoorbereiding</span></footer></article>${exercisePages}</body></html>`
}
function openTrainingSheet(id){const t=trainingById(id);if(!t)return;openPrintableDocument(buildTrainingSheetHtml(t),'Trainings-PDF')}

function renderTrainingDay(){const t=trainingById(ui.trainingId)||nextTraining();if(!t)return `<div class="empty">Geen training beschikbaar.</div>`;ui.trainingId=t.id;const squad=eventSquad(t),c=eventAttendanceCounts(t),meta=trainingTemplateMeta(t);return `<div class="focus-mode-head"><button class="btn ghost" data-go="trainings">← Trainingen</button><span class="badge green">TRAININGSDAG</span></div><section class="card focus-hero"><p class="eyebrow">${esc(t.templateName||meta.name)} · ${fmtLong(t.date)}</p><h2>${esc(t.focus||'Training')}</h2><p>${esc(t.startTime||state.team.trainingTime||'')} · ${squad.length} spelers</p>${t.trainingObjective?`<div class="focus-objective"><strong>Doel</strong><span>${esc(t.trainingObjective)}</span></div>`:''}<div class="focus-actions"><button class="btn primary" data-attendance="${t.id}">Aanwezigheid ${c.filled}/${c.total}</button><button class="btn ghost" data-training-pdf="${t.id}">PDF / delen</button><button class="btn ghost" data-quick-reflection="training" data-reflection-id="${t.id}">2-min reflectie</button><button class="btn ghost" data-training-review="${t.id}">KNVB-check & evaluatie</button><button class="btn ghost" data-save-training-template="${t.id}">Als template</button><button class="btn ghost" data-duplicate-training="${t.id}">Dupliceer</button><button class="btn danger" data-delete-training="${t.id}">Verwijderen</button></div></section><section class="card"><div class="card-head"><div><p class="eyebrow">PLAN</p><h2>Oefeningen & coachpunten</h2></div></div><div class="plan-stack">${(t.planItems||[]).map((pi,i)=>planItemHtml(t,pi,i)).join('')||'<div class="empty">Nog geen oefeningen.</div>'}</div></section>`}
function renderMatchDay(){const m=matchById(ui.matchId)||nextMatch();if(!m)return `<div class="empty">Geen wedstrijd beschikbaar.</div>`;ui.matchId=m.id;const warn=selectionWarnings(m),selected=[...new Set([...Object.values(m.lineup||{}).filter(Boolean),...(m.benchIds||[])])].map(playerById).filter(Boolean);return `<div class="focus-mode-head"><button class="btn ghost" data-go="matches">← Wedstrijden</button><span class="badge blue">WEDSTRIJDDAG</span></div><section class="card focus-hero"><p class="eyebrow">${fmtLong(m.date)} · ${esc(m.competition||'Wedstrijd')}</p><h2>${esc(activeTeam()?.name||'')} · ${esc(m.opponent||'Tegenstander')}</h2><p>${esc(m.homeAway||'')} · ${esc(m.startTime||'')} · verzamelen ${esc(m.gatherTime||'–')}</p>${warn.length?`<div class="warning-box"><strong>Selectiecontrole</strong><ul>${warn.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:'<div class="success-box">Selectiecontrole: basis en bank zijn compleet genoeg voor het wedstrijdblad.</div>'}<div class="focus-actions"><button class="btn primary" data-match-sheet="${m.id}">📄 Wedstrijdblad</button><button class="btn ghost" data-match-sheet-remarks="${m.id}">✎ Opmerkingen</button><button class="btn ghost" data-match-analysis="${m.id}">Analyse / 5 W's</button><button class="btn ghost" data-quick-reflection="match" data-reflection-id="${m.id}">2-min reflectie</button><button class="btn ghost" data-edit-bench>Bank kiezen</button><button class="btn ghost" data-duplicate-match="${m.id}">Dupliceer</button></div></section><div class="grid two"><section class="card"><div class="card-head"><div><p class="eyebrow">SELECTIE</p><h2>${selected.length} spelers</h2></div></div><div class="chips">${selected.map(p=>`<span class="chip">${esc(p.name)}</span>`).join('')}</div></section><section class="card"><div class="card-head"><div><p class="eyebrow">WEDSTRIJDPLAN</p><h2>Coachfocus</h2></div></div><div class="list-row"><span>Teamdoel</span><strong>${esc(m.plan?.teamGoal||'–')}</strong></div><div class="list-row"><span>Pressing</span><strong>${esc(m.plan?.pressing||'–')}</strong></div><div class="list-row"><span>Opbouw</span><strong>${esc(m.plan?.buildUp||'–')}</strong></div></section></div><section class="card" style="margin-top:16px"><div class="card-head"><div><p class="eyebrow">LIVE INVOER</p><h2>Spelers</h2></div></div><div class="match-stat-list">${selected.map(p=>{const st=m.playerStats?.[p.id]||{};return `<button class="match-stat-player" data-edit-match-stat="${p.id}"><span class="match-stat-name"><strong>${esc(p.name)}</strong><small>${Object.values(m.lineup||{}).includes(p.id)?'Basis':'Bank'}${st.coachRating?` · ★ ${Number(st.coachRating).toFixed(1)}`:''}</small></span><span><b>${number(st.minutes)}</b><small>min</small></span><span><b>${number(st.goals)}</b><small>G</small></span><span><b>${number(st.assists)}</b><small>A</small></span><span class="stat-chevron">›</span></button>`}).join('')}</div></section>`}
function globalSearchItems(q){q=q.toLowerCase().trim();if(!q)return [];const out=[];state.players.filter(p=>p.active!==false&&[p.name,p.position,p.notes,p.developmentGoals].join(' ').toLowerCase().includes(q)).slice(0,8).forEach(p=>out.push({type:'player',id:p.id,title:p.name,sub:'Speler · '+(p.position||'geen positie')}));state.trainings.filter(t=>[t.focus,t.notes,t.coachNotes,t.date].join(' ').toLowerCase().includes(q)).slice(0,6).forEach(t=>out.push({type:'training',id:t.id,title:t.focus||'Training',sub:'Training · '+fmtDate(t.date)}));state.matches.filter(m=>[m.opponent,m.competition,m.venue,m.date].join(' ').toLowerCase().includes(q)).slice(0,6).forEach(m=>out.push({type:'match',id:m.id,title:m.opponent||'Wedstrijd',sub:'Wedstrijd · '+fmtDate(m.date)}));state.exercises.filter(x=>[x.name,x.category,x.description,(x.tags||[]).join(' ')].join(' ').toLowerCase().includes(q)).slice(0,8).forEach(x=>out.push({type:'exercise',id:x.id,title:x.name,sub:'Oefening · '+x.category}));state.coachNotes.filter(n=>[n.text,n.category].join(' ').toLowerCase().includes(q)).slice(0,5).forEach(n=>out.push({type:'note',id:n.id,title:(n.text||'Notitie').slice(0,55),sub:'Coachnotitie · '+fmtDate(n.date)}));KNOWLEDGE_LIBRARY.filter(k=>[k.title,k.category,k.summary,(k.points||[]).join(' '),(k.terms||[]).join(' ')].join(' ').toLowerCase().includes(q)).slice(0,8).forEach(k=>out.push({type:'knowledge',id:k.id,title:k.title,sub:'Kennisbank · '+k.category}));return out.slice(0,25)}
function openGlobalSearch(){modal('Zoeken in Football Coach',`<div class="field"><label>Zoek speler, training, wedstrijd, oefening, notitie of kennisbron</label><input id="globalSearchInput" class="input" autofocus placeholder="Bijv. Sem, PMRS, pressing, 5 W’s, rondo..."></div><div id="globalSearchResults" class="global-search-results"><div class="empty">Begin met typen.</div></div>`,null,{saveText:'Sluiten',onSave:()=>closeModal()});const inp=$('#globalSearchInput'),box=$('#globalSearchResults');const run=()=>{const items=globalSearchItems(inp.value);box.innerHTML=items.length?items.map(x=>`<button type="button" class="global-search-result" data-global-type="${x.type}" data-global-id="${x.id}"><strong>${esc(x.title)}</strong><span>${esc(x.sub)}</span></button>`).join(''):'<div class="empty">Geen resultaten.</div>'};inp.oninput=run;setTimeout(()=>inp.focus(),50)}
function openGlobalResult(type,id){closeModal();if(type==='player'){ui.playerId=id;return setPage('player')}if(type==='training'){ui.trainingId=id;return setPage('trainings')}if(type==='match'){ui.matchId=id;return setPage('matches')}if(type==='exercise'){ui.exerciseSearch=exerciseById(id)?.name||'';return setPage('exercises')}if(type==='note')return setPage('notes');if(type==='knowledge'){ui.knowledgeSearch=KNOWLEDGE_LIBRARY.find(k=>k.id===id)?.title||'';return setPage('knowledge')}}
function isIOSPrintDevice(){return /iPad|iPhone|iPod/.test(navigator.userAgent)||(navigator.platform==='MacIntel'&&navigator.maxTouchPoints>1)}
function openPrintableDocument(html,label='Document'){
  if(isIOSPrintDevice()){
    try{const blob=new Blob([html],{type:'text/html;charset=utf-8'}),url=URL.createObjectURL(blob);window.location.assign(url);return}catch(err){console.warn('iOS print preview fallback',err)}
  }
  const w=window.open('','_blank');if(!w){toast(`Kon ${label.toLowerCase()} niet openen. Sta pop-ups toe of probeer opnieuw.`);return}w.document.open();w.document.write(html);w.document.close();w.focus();
}
function buildPlayerReportHtml(p){const teamId=p.primaryTeamId||ui.teamId,v=calculatePlayerValue(p,teamId),mt=matchTotals(p.id,teamId),pct=attendancePct(p.id,teamId),notes=state.coachNotes.filter(n=>n.playerId===p.id).sort((a,b)=>(b.date||'').localeCompare(a.date||'')).slice(0,10),ratings=Object.entries(SCORE_LABELS).map(([k,l])=>({label:l,value:Math.round(clamp(number(p.scores?.[k]),0,100))})),idpGoals=(p.idp?.goals||[]),why=valueExplanation(p,v),team=state.teams.find(t=>t.id===p.primaryTeamId),season=state.team.season||'',availability=p.availabilityStatus||'Fit';const ratingRows=ratings.map(r=>`<div class="rating-row"><span>${esc(r.label)}</span><div class="rating-track"><i style="width:${r.value}%"></i></div><strong>${r.value||'–'}</strong></div>`).join('');const valueRows=Object.entries(v.components).map(([k,val])=>`<div class="rating-row compact"><span>${esc({usage:'Wedstrijdgebruik',training:'Training',performance:'Prestatie',form:'Vorm',development:'Ontwikkeling',reliability:'Beschikbaarheid'}[k])}</span><div class="rating-track"><i style="width:${val}%"></i></div><strong>${val}</strong></div>`).join('');return `<!doctype html><html lang="nl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Spelersrapport ${esc(p.name)}</title><style>@page{size:A4;margin:0}*{box-sizing:border-box;-webkit-print-color-adjust:exact!important;print-color-adjust:exact!important}html,body{margin:0;padding:0;font-family:Inter,Arial,sans-serif;color:#17392f;background:#e8efeb}.actions{position:sticky;top:0;z-index:4;display:flex;justify-content:center;gap:10px;padding:10px;background:#102f26}.actions button{border:0;border-radius:10px;padding:10px 16px;font-weight:800}.actions .primary{background:#0b6b44;color:#fff}.share-hint{max-width:210mm;margin:8px auto;padding:8px 12px;border-radius:10px;background:#eef6f1;color:#34584b;text-align:center;font-size:12px;font-weight:700}.sheet{width:210mm;min-height:297mm;margin:12px auto;background:#fff;padding:0 12mm 10mm;box-shadow:0 16px 45px #17392f22;overflow:hidden}.hero{margin:0 -12mm;background:linear-gradient(135deg,#083f2f,#0b6b44);color:#fff;padding:10mm 12mm 8mm;position:relative}.hero:after{content:'FS';position:absolute;right:9mm;top:0;font-weight:900;font-size:58pt;opacity:.055}.club{display:flex;align-items:center;gap:5mm}.logo{width:15mm;height:15mm;object-fit:contain;background:#fff;border-radius:50%;padding:1.5mm}.club small{display:block;letter-spacing:1.6px;text-transform:uppercase;opacity:.8}.club strong{font-size:15pt}.player-hero{display:grid;grid-template-columns:1fr auto;gap:8mm;align-items:end;margin-top:7mm}.player-name{font-size:30pt;line-height:1;margin:0 0 2mm}.player-sub{opacity:.85;font-size:10pt}.value-pill{text-align:right;background:#ffffff14;border:1px solid #ffffff36;border-radius:4mm;padding:4mm 5mm;min-width:42mm}.value-pill span{display:block;font-size:7pt;text-transform:uppercase;letter-spacing:1px}.value-pill strong{font-size:19pt}.meta{display:grid;grid-template-columns:repeat(5,1fr);gap:2.2mm;margin-top:-4mm;position:relative}.meta div{background:#fff;border:1px solid #dce7e0;border-radius:3mm;padding:3mm;min-height:17mm;box-shadow:0 3px 12px #17392f0c}.meta span,.kpi span{display:block;color:#708279;font-size:6.8pt;text-transform:uppercase;letter-spacing:.6px}.meta strong{display:block;margin-top:1mm;font-size:9pt}.kpis{display:grid;grid-template-columns:repeat(6,1fr);gap:2.2mm;margin:5mm 0}.kpi{background:#f5f8f6;border-radius:3mm;padding:3mm;border:1px solid #e1e9e4}.kpi strong{display:block;font-size:15pt;margin-top:1mm}.section{margin-top:5mm}.section-head{display:flex;align-items:end;justify-content:space-between;border-bottom:1px solid #cfdcd4;padding-bottom:1.5mm;margin-bottom:3mm}.section-head h2{margin:0;color:#07583a;font-size:14pt}.section-head span{font-size:7pt;color:#7a8a82;text-transform:uppercase;letter-spacing:1px}.two{display:grid;grid-template-columns:1fr 1fr;gap:3mm}.panel{border:1px solid #dce6e0;border-radius:3mm;padding:3.5mm;background:#fbfcfb;break-inside:avoid}.panel h3{margin:0 0 1.8mm;color:#07583a;font-size:10pt}.panel p{margin:0;font-size:8.3pt;line-height:1.45;color:#3d544a}.rating-row{display:grid;grid-template-columns:31mm 1fr 10mm;gap:2.5mm;align-items:center;margin:2mm 0;font-size:8pt}.rating-row.compact{grid-template-columns:34mm 1fr 10mm;margin:1.6mm 0}.rating-track{height:3mm;border-radius:99px;background:#e6eee9;overflow:hidden}.rating-track i{display:block;height:100%;border-radius:99px;background:linear-gradient(90deg,#0b6b44,#37a36f)}.rating-row strong{text-align:right}.why{display:grid;grid-template-columns:1fr 1fr;gap:2mm;margin-top:3mm}.why div{background:#eef6f1;border-radius:2mm;padding:2.2mm 2.6mm;font-size:7.6pt}.notes{display:grid;gap:2mm}.note{border-left:3px solid #1b7b55;background:#f7faf8;padding:2.5mm 3mm;border-radius:0 2mm 2mm 0;font-size:7.7pt;line-height:1.4}.note strong{color:#07583a}.footer{display:flex;justify-content:space-between;border-top:1px solid #d8e3dd;margin-top:6mm;padding-top:2mm;font-size:6.5pt;color:#839089;text-transform:uppercase;letter-spacing:.8px}.avoid{break-inside:avoid}@media(max-width:800px){.sheet{width:100%;margin:0;box-shadow:none;padding-left:16px;padding-right:16px}.hero{margin-left:-16px;margin-right:-16px;padding-left:16px;padding-right:16px}.player-hero{grid-template-columns:1fr}.value-pill{text-align:left}.meta{grid-template-columns:1fr 1fr}.kpis{grid-template-columns:1fr 1fr 1fr}.two{grid-template-columns:1fr}}@media print{html,body{background:#fff}.actions,.share-hint{display:none!important}.sheet{width:210mm!important;min-height:297mm!important;margin:0!important;box-shadow:none!important;padding:0 12mm 10mm!important}.hero{margin:0 -12mm!important}.meta{grid-template-columns:repeat(5,1fr)!important}.kpis{grid-template-columns:repeat(6,1fr)!important}.two{grid-template-columns:1fr 1fr!important}}</style></head><body><div class="actions"><button onclick="if(history.length>1){history.back()}else{window.close()}">← Terug</button><button class="primary" onclick="window.print()">Print / bewaar & deel als PDF</button></div><div class="share-hint">Op iPhone/iPad: tik op Print, vergroot de voorbeeldpagina met twee vingers en kies daarna Delen om de PDF te bewaren of te versturen.</div><main class="sheet"><header class="hero"><div class="club"><img class="logo" src="${FULL_SPEED_LOGO_DATA}" alt="Full Speed"><div><small>${esc(season?`Seizoen ${season}`:'Spelersrapport')}</small><strong>${esc(state.club?.name||'DSV Full Speed')} · ${esc(team?.name||teamName(p.primaryTeamId))}</strong></div></div><div class="player-hero"><div><h1 class="player-name">${esc(p.name)}</h1><div class="player-sub">${esc(p.position||'Positie niet ingevuld')}${p.number?` · #${esc(p.number)}`:''}</div></div><div class="value-pill"><span>Interne spelerswaarde</span><strong>${fmtEuro(v.marketValue)}</strong><span>${Math.round(v.score)}/100 · vorm ${v.form}</span></div></div></header><section class="meta"><div><span>Primair team</span><strong>${esc(teamName(p.primaryTeamId))}</strong></div><div><span>Beschikbaarheid</span><strong>${esc(availability)}</strong></div><div><span>Voorkeursbeen</span><strong>${esc(p.preferredFoot||'–')}</strong></div><div><span>Rol in team</span><strong>${esc(p.teamRole||'–')}</strong></div><div><span>Geboortedatum</span><strong>${p.birthDate?fmtDate(p.birthDate):'–'}</strong></div></section><section class="kpis"><div class="kpi"><span>Trainingsopkomst</span><strong>${pct===null?'–':pct+'%'}</strong></div><div class="kpi"><span>Wedstrijden</span><strong>${mt.games}</strong></div><div class="kpi"><span>Basis</span><strong>${mt.starts}</strong></div><div class="kpi"><span>Minuten</span><strong>${mt.minutes}</strong></div><div class="kpi"><span>Goals</span><strong>${mt.goals}</strong></div><div class="kpi"><span>Assists</span><strong>${mt.assists}</strong></div></section><section class="section avoid"><div class="section-head"><h2>Ontwikkelratings</h2><span>1–100</span></div>${ratingRows}</section><section class="section"><div class="section-head"><h2>Team in beeld</h2><span>Voetbal & persoon</span></div><div class="two"><div class="panel"><h3>Voetbalkwaliteiten</h3><p>${nl2br(p.footballStrengths||'Nog niet ingevuld')}</p></div><div class="panel"><h3>Voetbalontwikkeling</h3><p>${nl2br(p.footballDevelopment||'Nog niet ingevuld')}</p></div><div class="panel"><h3>Persoonskenmerken</h3><p>${nl2br(p.personStrengths||'Nog niet ingevuld')}</p></div><div class="panel"><h3>Persoonsontwikkeling</h3><p>${nl2br(p.personDevelopment||'Nog niet ingevuld')}</p></div><div class="panel"><h3>Coachaanpak</h3><p>${nl2br(p.coachApproach||'Nog niet ingevuld')}</p></div><div class="panel"><h3>Ontwikkeldoelen</h3><p>${nl2br(p.developmentGoals||'Nog niet ingevuld')}</p></div></div></section>${idpGoals.length?`<section class="section avoid"><div class="section-head"><h2>Individueel ontwikkelplan</h2><span>${idpGoals.filter(g=>(g.status||'Actief')==='Actief').length} actief</span></div><div class="two">${idpGoals.map(g=>`<div class="panel"><h3>${esc(g.title)}</h3><p><strong>${esc(g.area||'Ontwikkeling')} · ${esc(g.status||'Actief')} · ${number(g.progress)||0}/100</strong></p><p>${nl2br(g.measure||'Geen meetpunt ingevuld')}</p><p>${nl2br(g.actions||'Geen acties ingevuld')}</p>${g.reviewDate?`<p><strong>Evaluatie:</strong> ${fmtDate(g.reviewDate)}</p>`:''}</div>`).join('')}</div></section>`:''}<section class="section avoid"><div class="section-head"><h2>Spelerswaarde</h2><span>Transparante interne berekening</span></div>${valueRows}<div class="why">${why.map(x=>`<div>${esc(x)}</div>`).join('')}</div></section><section class="section"><div class="section-head"><h2>Recente coachnotities</h2><span>${notes.length} notities</span></div><div class="notes">${notes.map(n=>`<div class="note"><strong>${fmtDate(n.date)} · ${esc(n.category||'Notitie')}</strong><br>${nl2br(n.text)}</div>`).join('')||'<div class="panel">Geen coachnotities geregistreerd.</div>'}</div></section><footer class="footer"><span>${esc(state.club?.name||'DSV Full Speed')}</span><span>${esc(p.name)} · ${TODAY()}</span></footer></main></body></html>`}
function exportPlayerReport(id){const p=playerById(id);if(!p)return;openPrintableDocument(buildPlayerReportHtml(p),'Spelersrapport')}
function archiveSeason(){const season=state.team.season||'huidig seizoen';const next=prompt('Nieuw seizoen na archiveren:',season.replace(/(\d{4})\/(\d{4})/,(_,a,b)=>`${b}/${Number(b)+1}`));if(!next)return;if(!confirm(`Seizoen ${season} archiveren en wedstrijd-/trainingsdata leeg starten voor ${next}?\n\nEr wordt ook een JSON-back-up gedownload.`))return;const snapshot=clone(state);downloadJson(snapshot,`football-coach-archief-${season.replace('/','-')}.json`);let archives=[];try{archives=JSON.parse(localStorage.getItem(ARCHIVE_KEY)||'[]')}catch{}archives.unshift({season,at:new Date().toISOString(),data:snapshot});localStorage.setItem(ARCHIVE_KEY,JSON.stringify(archives.slice(0,3)));state.trainings=[];state.matches=[];state.seasonItems=[];state.coachNotes=[];state.coachReflections=[];state.players.forEach(p=>{p.valueHistory=[]});state.team.season=next;ui.trainingId=ui.matchId=ui.attendanceId=null;save();toast(`Seizoen ${season} gearchiveerd`)}
function downloadJson(obj,name){const blob=new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),500)}

function defaultTeam(){return state.teams?.[0]||null}
function activeTeam(){return state.teams.find(t=>t.id===ui.teamId)||defaultTeam()}
function teamName(id){return state.teams.find(t=>t.id===id)?.name||'Geen team'}
function playerById(id){return state.players.find(p=>p.id===id)}
function exerciseById(id){return state.exercises.find(e=>e.id===id)}
function trainingById(id){return state.trainings.find(t=>t.id===id)}
function matchById(id){return state.matches.find(m=>m.id===id)}
function tacticById(id){return state.tactics.find(t=>t.id===id)}
function eventById(id){return trainingById(id)||matchById(id)}
function eventType(ev){if(!ev)return 'Activiteit';return state.trainings.some(x=>x.id===ev.id)?'Training':'Wedstrijd'}
function playersForTeam(teamId){return state.players.filter(p=>p.active!==false&&p.primaryTeamId===teamId).sort((a,b)=>a.name.localeCompare(b.name,'nl'))}
function availablePlayersForTeam(teamId){return state.players.filter(p=>p.active!==false&&(p.teamIds||[]).includes(teamId)).sort((a,b)=>a.name.localeCompare(b.name,'nl'))}
function eventSquad(ev){const ids=Array.isArray(ev?.squadPlayerIds)&&ev.squadPlayerIds.length?ev.squadPlayerIds:null;return ids?ids.map(playerById).filter(p=>p&&p.active!==false):playersForTeam(ev?.teamId||activeTeam()?.id)}
function eventPlayerIds(ev){return eventSquad(ev).map(p=>p.id)}
function eventAttendanceCounts(ev){const ids=eventPlayerIds(ev),vals=ids.map(id=>ev.attendance?.[id]||'');return {total:ids.length,filled:vals.filter(Boolean).length,present:vals.filter(presentStatus).length,absent:vals.filter(absentStatus).length,unknown:vals.filter(v=>!v).length}}
function combinedSchedule(teamId=ui.teamId){return [
  ...state.trainings.filter(x=>!teamId||x.teamId===teamId).map(x=>({...x,type:'Training'})),
  ...state.matches.filter(x=>!teamId||x.teamId===teamId).map(x=>({...x,type:'Wedstrijd'})),
  ...(state.seasonItems||[]).filter(x=>!teamId||!x.teamId||x.teamId===teamId)
].sort((a,b)=>a.date.localeCompare(b.date)||(a.startTime||'').localeCompare(b.startTime||''))}
function nextTraining(teamId=ui.teamId){return state.trainings.filter(t=>(!teamId||t.teamId===teamId)&&!isCancelled(t)&&t.date>=TODAY()).sort((a,b)=>a.date.localeCompare(b.date))[0]||null}
function latestTraining(teamId=ui.teamId){return state.trainings.filter(t=>(!teamId||t.teamId===teamId)&&!isCancelled(t)&&t.date<=TODAY()).sort((a,b)=>b.date.localeCompare(a.date))[0]||null}
function nextMatch(teamId=ui.teamId){return state.matches.filter(m=>(!teamId||m.teamId===teamId)&&!isCancelled(m)&&m.date>=TODAY()).sort((a,b)=>a.date.localeCompare(b.date))[0]||null}
function attendancePct(playerId,teamId=ui.teamId){const past=state.trainings.filter(t=>(!teamId||t.teamId===teamId)&&!isCancelled(t)&&t.date<=TODAY()&&t.attendance&&t.attendance[playerId]);if(!past.length)return null;return Math.round(past.filter(t=>presentStatus(t.attendance[playerId])).length/past.length*100)}
function matchTotals(playerId,teamId=ui.teamId){let games=0,starts=0,minutes=0,goals=0,assists=0,yellow=0,red=0,ratings=[];state.matches.filter(m=>(!teamId||m.teamId===teamId)&&!isCancelled(m)).forEach(m=>{const s=m.playerStats?.[playerId];if(s){games++;starts+=(s.started||Object.values(m.lineup||{}).includes(playerId))?1:0;minutes+=number(s.minutes);goals+=number(s.goals);assists+=number(s.assists);yellow+=number(s.yellow);red+=number(s.red);if(number(s.coachRating)>0)ratings.push(number(s.coachRating))}});return {games,starts,minutes,goals,assists,yellow,red,coachRating:ratings.length?Math.round(ratings.reduce((a,b)=>a+b,0)/ratings.length*10)/10:null}}
function statusBadge(status){if(!status)return '<span class="badge">Niet ingevuld</span>';const c=presentStatus(status)?'green':status.includes('blessure')||status.includes('ziek')?'red':status.includes('vakantie')||status.includes('school')?'orange':'';return `<span class="badge ${c}">${esc(status)}</span>`}
function teamOptions(selected){return state.teams.map(t=>`<option value="${t.id}" ${t.id===selected?'selected':''}>${esc(t.name)}</option>`).join('')}
