function load(){try{const raw=localStorage.getItem(STORAGE_KEY)||localStorage.getItem(LEGACY_STORAGE_KEY);state=raw?JSON.parse(raw):clone(window.STARTER_DATA);normalize();if(!localStorage.getItem(STORAGE_KEY))save({render:false,sync:false})}catch{state=clone(window.STARTER_DATA);normalize()}}
function save({render=true,sync=true,skipUndo=false,activity=null}={}){
  const previous=localStorage.getItem(STORAGE_KEY);
  if(!skipUndo&&!undoBusy&&previous){
    try{const now=JSON.stringify(state);if(previous!==now){undoStack.push(previous);undoStack=undoStack.slice(-20)}}catch{}
  }
  state.meta.updatedAt=new Date().toISOString();
  logActivity(activity||`${pageInfo()?.[0]||'App'} aangepast`);
  recordValueSnapshots();
  localStorage.setItem(STORAGE_KEY,JSON.stringify(state));
  autoBackupMaybe();
  const lbl=$('#saveStateLabel');if(lbl)lbl.textContent='Opgeslagen '+new Date().toLocaleTimeString('nl-NL',{hour:'2-digit',minute:'2-digit'});
  updateUndoButton();updateConnectionStatus();
  if(render)renderPage();
  if(sync&&syncConfigured()&&navigator.onLine){clearTimeout(syncTimer);syncTimer=setTimeout(()=>pushSync(true),500)}
}
function toast(msg){const t=$('#toast');if(!t)return;t.textContent=msg;t.classList.add('show');setTimeout(()=>t.classList.remove('show'),2400)}
function setPage(page){
  ui.page=page;
  const activeNavPage=page==='player'?'players':page;
  $$('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===activeNavPage));
  renderPage();
  window.scrollTo({top:0,behavior:'smooth'});
}
